import{_ as e,o,c as t,a2 as r}from"./chunks/framework.Bi388yPt.js";const u=JSON.parse('{"title":"项目边界","description":"","frontmatter":{},"headers":[],"relativePath":"guide/scope.md","filePath":"guide/scope.md"}'),i={name:"guide/scope.md"};function c(s,a,n,h,d,l){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="项目边界" tabindex="-1">项目边界 <a class="header-anchor" href="#项目边界" aria-label="Permalink to &quot;项目边界&quot;">​</a></h1><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>服务 RESTful API 及其变体，保留模型化与链式操作。标准接口近乎免配；服务级 scheme 一次适配共性规则，资源与操作继承，配置主要处理例外。少量特殊接口必须显式配置，并尽量简化声明。不以通用 RPC 或任意数据源访问作为目标。</p><p>主包不依赖 Axios，不暴露 Axios 类型。主包定义资源模型、链式上下文、HTTP 请求与结果契约、默认推导、scheme 规则和扩展接入点。不要为每个标准接口重复声明 URL、方法和参数转换。</p><h2 id="扩展" tabindex="-1">扩展 <a class="header-anchor" href="#扩展" aria-label="Permalink to &quot;扩展&quot;">​</a></h2><p>请求实现、Mock、缓存、Pinia 等集成都属于扩展能力，不进入主包。具体扩展实现与交付范围由各包的公开入口和维护资料说明。</p><p>扩展分为随主包迭代的正式配套与独立维护的第三方。扩展可采用伪三方方式：即使同一作者、同一仓库维护，也只使用公开契约，独立声明兼容范围、独立发布，不承诺同步升级。不设统一版本或固定版本组。各包不因同一仓库而共享固定版本。</p><p>扩展对核心使用 workspace peer dependency；具体兼容范围应在发布时明确，开发版本不能视作已发布的兼容承诺。</p><h2 id="mock" tabindex="-1">Mock <a class="header-anchor" href="#mock" aria-label="Permalink to &quot;Mock&quot;">​</a></h2><p>Mock 是本项目提供的 HTTP 调试扩展，必须服从 HTTP。复用资源推导和 scheme 适配后的最终请求，按方法、URL、参数、请求体匹配并返回状态码、响应头、响应体，可模拟延迟与网络错误。不得绕过 HTTP 流程直接按资源操作返回业务结果。</p><h2 id="缓存和状态管理" tabindex="-1">缓存和状态管理 <a class="header-anchor" href="#缓存和状态管理" aria-label="Permalink to &quot;缓存和状态管理&quot;">​</a></h2><p>缓存作为可选扩展，由本库定义数据结构、键、有效期和失效规则。允许替换存储介质，不负责适配任意业务 Store。Pinia 等封装在主包基础上集成状态管理，不改变主包的数据访问边界。</p><h2 id="维护原则" tabindex="-1">维护原则 <a class="header-anchor" href="#维护原则" aria-label="Permalink to &quot;维护原则&quot;">​</a></h2><p>使用者易用、易学优先。内部复杂度可以存在，但对外概念与行为必须清晰、稳定。保留模型化和链式特征，优先简化概念，不以减少内部实现代码为目的牺牲调用体验。通用能力优先评估成熟依赖，避免继续绑定原工具集临包。</p>',14)])])}const _=e(i,[["render",c]]);export{u as __pageData,_ as default};
